"use strict";
const assert = require("node:assert/strict");
const fs = require("node:fs");
const screen = fs.readFileSync("app/(tabs)/community-events.tsx", "utf8");
const admin = fs.readFileSync("app/(admin)/community-attendance.tsx", "utf8");
const rules = fs.readFileSync("firestore.rules", "utf8");
const cut=(a,b)=>{const x=screen.indexOf(a),y=screen.indexOf(b,x+1);assert(x>=0&&y>x,"Attendance block missing");return screen.slice(x,y);};
const web=cut('{!selectedParticipation?.attendanceVerified && (','{selectedEvent.status === "upcoming" && <Text style={styles.webAttendanceHint}>');
assert(web.includes('accessibilityLabel={"Time In for " + selectedEvent.title}'),"Time In is visibly rendered");
assert(web.includes('accessibilityLabel={"Time Out from " + selectedEvent.title}'),"Time Out is visibly rendered");
assert(web.includes('selectedEvent.status !== "active"'),"Both buttons remain gated until event is ongoing");
assert(web.includes('!selectedParticipation?.checkedInAt'),"Time Out requires recorded Time In");
assert(web.includes('!!selectedParticipation?.checkedOutAt'),"Time Out can only be recorded once");
assert(web.includes('recordSelfAttendance(selectedEvent, attendanceConfirmation.action)'),"Confirmation calls original secured Firestore transaction");
assert(web.includes('Admin > Event Attendance'),"Explain exactly how Admin unlocks attendance");
assert(screen.includes("Waiting for Admin Start Event"),"Upcoming events show helpful status instead of misleading Time In state");
assert(screen.includes("eventScheduleHasPassed(selectedEvent)"),"Past upcoming event cannot be backdated");
assert(screen.includes('await runTransaction(db, async (transaction) => {'),"Keep original atomic attendance transaction");
assert(screen.includes('currentEvent.status !== "active"'),"Transactional status recheck prevents bypass");
assert(screen.includes('checkedInAt: serverTimestamp()')&&screen.includes('checkedOutAt: serverTimestamp()'),"Keep authentic server times");
assert(admin.includes('onPress={() => void changeStatus("active")}')&&admin.includes('status: "active"'),"Admin Start Event control still unlocks attendance");
assert(rules.includes("eventBefore().status == 'active'"),"Keep server-side active-only Time In/Out");
assert(rules.includes("request.resource.data.attendanceVerified == false"),"Volunteer never self-verifies");
console.log("PASS: separately visible Time In/Time Out, approved-event gating, Admin start, Firestore timestamps, no backdating");
